export type EntityFormProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  presentation?: "dialog" | "sheet"
  onSubmit: (formData: FormData) => Promise<void> | void
  onDelete?: () => Promise<void> | void
  submitLabel?: string
  cancelLabel?: string
  deleteLabel?: string
  pendingLabel?: string
  /** Shown when onSubmit or onDelete rejects and onError is omitted. */
  errorLabel?: string
  onError?: (error: unknown) => void
  busy?: boolean
  children?: React.ReactNode
  className?: string
}

/**
 * Create or edit one record in a dialog or a sheet.
 *
 * Position is not part of the form. The parent should pass the existing
 * `position` through `keepPosition` so a save does not send the row to the end.
 * While `busy` is true (an upload, for example) submit stays disabled.
 */
export function EntityForm({
  open,
  onOpenChange,
  title,
  description,
  presentation = "dialog",
  onSubmit,
  onDelete,
  submitLabel = "Save",
  cancelLabel = "Cancel",
  deleteLabel = "Delete",
  pendingLabel = "Saving…",
  errorLabel = "Could not save",
  onError,
  busy = false,
  children,
  className,
}: EntityFormProps) {
  const [pending, setPending] = React.useState(false)
  const [confirmOpen, setConfirmOpen] = React.useState(false)
  const locked = busy || pending

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    if (locked) return
    const formData = new FormData(event.currentTarget)
    setPending(true)
    try {
      await onSubmit(formData)
      onOpenChange(false)
    } catch (error) {
      if (onError) onError(error)
      else toast.error(error instanceof Error && error.message ? error.message : errorLabel)
    } finally {
      setPending(false)
    }
  }

  const form = (
    <form className="flex min-h-0 flex-1 flex-col gap-4" onSubmit={handleSubmit}>
      <div className={cn("flex flex-col gap-3", className)}>{children}</div>
      <div className="mt-auto flex flex-wrap items-center gap-2">
        {onDelete ? (
          <Button type="button" variant="destructive" onClick={() => setConfirmOpen(true)} disabled={locked}>
            {deleteLabel}
          </Button>
        ) : null}
        <div className="ml-auto flex gap-2">
          <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={locked}>
            {cancelLabel}
          </Button>
          <Button type="submit" disabled={locked}>
            {pending ? pendingLabel : submitLabel}
          </Button>
        </div>
      </div>
    </form>
  )

  return (
    <>
      {presentation === "sheet" ? (
        <Sheet open={open} onOpenChange={onOpenChange}>
          <SheetContent className="flex w-full flex-col sm:max-w-md" side="right">
            <SheetHeader>
              <SheetTitle>{title}</SheetTitle>
              {description ? <SheetDescription>{description}</SheetDescription> : null}
            </SheetHeader>
            {form}
            <SheetFooter className="hidden" />
          </SheetContent>
        </Sheet>
      ) : (
        <Dialog open={open} onOpenChange={onOpenChange}>
          <DialogContent className="flex max-h-[85vh] flex-col sm:max-w-lg">
            <DialogHeader>
              <DialogTitle>{title}</DialogTitle>
              {description ? <DialogDescription>{description}</DialogDescription> : null}
            </DialogHeader>
            <div className="min-h-0 overflow-y-auto">{form}</div>
            <DialogFooter className="hidden" />
          </DialogContent>
        </Dialog>
      )}
      {onDelete ? (
        <ConfirmDelete
          open={confirmOpen}
          onOpenChange={setConfirmOpen}
          title={deleteLabel}
          description={description ?? title}
          confirmLabel={deleteLabel}
          cancelLabel={cancelLabel}
          errorLabel={errorLabel}
          onError={onError}
          onConfirm={async () => {
            await onDelete()
            setConfirmOpen(false)
            onOpenChange(false)
          }}
        />
      ) : null}
    </>
  )
}

export type ConfirmDeleteProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title?: string
  description?: string
  confirmLabel?: string
  cancelLabel?: string
  errorLabel?: string
  onError?: (error: unknown) => void
  onConfirm: () => Promise<void> | void
}

export function ConfirmDelete({
  open,
  onOpenChange,
  title = "Delete",
  description = "This cannot be undone.",
  confirmLabel = "Delete",
  cancelLabel = "Cancel",
  errorLabel = "Could not delete",
  onError,
  onConfirm,
}: ConfirmDeleteProps) {
  const [pending, setPending] = React.useState(false)
  return (
    <AlertDialog open={open} onOpenChange={onOpenChange}>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>{title}</AlertDialogTitle>
          <AlertDialogDescription>{description}</AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel disabled={pending}>{cancelLabel}</AlertDialogCancel>
          <AlertDialogAction
            variant="destructive"
            disabled={pending}
            onClick={(event) => {
              event.preventDefault()
              setPending(true)
              void (async () => {
                try {
                  await onConfirm()
                } catch (error) {
                  if (onError) onError(error)
                  else toast.error(error instanceof Error && error.message ? error.message : errorLabel)
                } finally {
                  setPending(false)
                }
              })()
            }}
          >
            {confirmLabel}
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

