import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import type { MediaAsset } from "@/lib/admin-types"
import { formatBytes, formatWhen } from "@/lib/format"
import { ConfirmDelete, EmptyState } from "@/components/ui/entity-form"

function isVideo(mime: string, url: string) {
  return mime.startsWith("video/") || /\.(mp4|webm|mov)($|\?)/i.test(url)
}

function matchesAcceptName(name: string, type: string, accept: string) {
  const rules = accept.split(",").map((rule) => rule.trim()).filter(Boolean)
  if (rules.length === 0) return true
  const lower = name.toLowerCase()
  return rules.some((rule) => {
    if (rule.startsWith(".")) return lower.endsWith(rule.toLowerCase())
    if (rule.endsWith("/*")) return type.startsWith(rule.slice(0, -1))
    return type === rule
  })
}

function matchesAccept(file: File, accept: string) {
  return matchesAcceptName(file.name, file.type, accept)
}

export type MediaFieldProps = {
  label: string
  value: string
  onChange: (value: string, asset?: MediaAsset | null) => void
  assets: readonly MediaAsset[]
  onUpload: (file: File) => Promise<MediaAsset>
  onBusyChange?: (busy: boolean) => void
  accept?: string
  hint?: string
  className?: string
  pickLabel?: string
  clearLabel?: string
  uploadLabel?: string
  uploadingLabel?: string
  dropLabel?: string
  emptyLibrary?: string
  uploadedMessage?: string
  uploadFailed?: string
  typeError?: string
}

export function MediaField({
  label,
  value,
  onChange,
  assets,
  onUpload,
  onBusyChange,
  accept = "image/*,video/mp4,video/webm",
  hint,
  className,
  pickLabel = "Library",
  clearLabel = "Remove",
  uploadLabel = "Upload",
  uploadingLabel = "Uploading…",
  dropLabel = "Drop a file",
  emptyLibrary = "Library is empty",
  uploadedMessage = "Uploaded",
  uploadFailed = "Upload failed",
  typeError = "That file type is not allowed.",
}: MediaFieldProps) {
  const inputId = React.useId()
  const [busy, setBusy] = React.useState(false)
  const activeUploads = React.useRef(0)
  const [dragging, setDragging] = React.useState(false)
  const [libraryOpen, setLibraryOpen] = React.useState(false)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const rootRef = React.useRef<HTMLDivElement>(null)

  React.useEffect(() => {
    onBusyChange?.(busy)
  }, [busy, onBusyChange])

  React.useEffect(() => {
    const form = rootRef.current?.closest("form")
    if (!form) return
    const block = (event: Event) => {
      if (!busy) return
      event.preventDefault()
      event.stopPropagation()
    }
    form.addEventListener("submit", block, true)
    return () => form.removeEventListener("submit", block, true)
  }, [busy])

  async function take(file: File | undefined) {
    if (!file) return
    if (!matchesAccept(file, accept)) {
      toast.error(typeError)
      return
    }
    activeUploads.current += 1
    setBusy(true)
    try {
      const asset = await onUpload(file)
      onChange(asset.url, asset)
      toast.success(uploadedMessage)
    } catch (error) {
      toast.error(error instanceof Error ? error.message : uploadFailed)
    } finally {
      activeUploads.current = Math.max(0, activeUploads.current - 1)
      if (activeUploads.current === 0) setBusy(false)
    }
  }

  const preview = value
  const video = preview ? isVideo("", preview) : false
  const library = assets.filter((asset) => matchesAcceptName(asset.filename, asset.mime, accept))

  return (
    <div ref={rootRef} className={cn("flex flex-col gap-2", className)} data-uploading={busy || undefined}>
      <span className="text-sm font-medium">{label}</span>
      <div
        className={cn(
          "flex flex-col gap-3 rounded-xl border border-dashed border-border bg-muted/40 p-3",
          dragging && "bg-accent",
        )}
        onDragOver={(event) => {
          event.preventDefault()
          setDragging(true)
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(event) => {
          event.preventDefault()
          setDragging(false)
          void take(event.dataTransfer.files[0])
        }}
      >
        {preview ? (
          video ? (
            <video src={preview} className="max-h-40 rounded-lg bg-background" controls muted />
          ) : (
            // Host URLs and blob previews. next/image is not available in a registry item.
            // eslint-disable-next-line @next/next/no-img-element
            <img src={preview} alt="" className="max-h-40 rounded-lg object-contain" />
          )
        ) : (
          <div className="grid h-24 place-items-center text-sm text-muted-foreground">
            <ImagePlus className="mb-1 size-5" />
            {busy ? uploadingLabel : dropLabel}
          </div>
        )}
        <div className="flex flex-wrap gap-2">
          <input
            ref={inputRef}
            id={inputId}
            type="file"
            accept={accept}
            className="sr-only"
            onChange={(event) => {
              void take(event.target.files?.[0])
              event.target.value = ""
            }}
          />
          <Button type="button" variant="outline" size="sm" disabled={busy} onClick={() => inputRef.current?.click()}>
            <Upload />
            {uploadLabel}
          </Button>
          <Button type="button" variant="outline" size="sm" disabled={busy} onClick={() => setLibraryOpen(true)}>
            {pickLabel}
          </Button>
          {value ? (
            <Button type="button" variant="ghost" size="sm" onClick={() => onChange("", null)}>
              {clearLabel}
            </Button>
          ) : null}
        </div>
      </div>
      {hint ? <p className="text-xs text-muted-foreground">{hint}</p> : null}
      <Dialog open={libraryOpen} onOpenChange={setLibraryOpen}>
        <DialogContent className="sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>{pickLabel}</DialogTitle>
          </DialogHeader>
          {library.length === 0 ? (
            <EmptyState title={emptyLibrary} />
          ) : (
            <ul className="grid max-h-80 grid-cols-3 gap-2 overflow-y-auto sm:grid-cols-4">
              {library.map((asset) => (
                <li key={asset.id}>
                  <button
                    type="button"
                    className="block w-full overflow-hidden rounded-lg ring-1 ring-foreground/10 hover:bg-muted"
                    onClick={() => {
                      onChange(asset.url, asset)
                      setLibraryOpen(false)
                    }}
                  >
                    <MediaPreview asset={asset} />
                    <span className="block truncate px-1 py-1 text-left text-xs">{asset.filename}</span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </DialogContent>
      </Dialog>
    </div>
  )
}

export type MediaLibraryProps = {
  assets: readonly MediaAsset[]
  onUpload: (file: File) => Promise<MediaAsset>
  onDelete: (id: string) => Promise<void> | void
  className?: string
  uploadLabel?: string
  uploadingLabel?: string
  dropLabel?: string
  emptyTitle?: string
  emptyDescription?: string
  uploadedMessage?: string
  uploadFailed?: string
  nameLabel?: string
  typeLabel?: string
  sizeLabel?: string
  addedLabel?: string
  deleteTitle?: string
  deleteDescription?: string
  deleteLabel?: string
  viewLabel?: string
  accept?: string
  typeError?: string
}

type SortKey = "createdAt" | "filename" | "size"

export function MediaLibrary({
  assets,
  onUpload,
  onDelete,
  className,
  uploadLabel = "Upload",
  uploadingLabel = "Uploading…",
  dropLabel = "Drop a file",
  emptyTitle = "No files yet",
  emptyDescription = "Upload an image or a video.",
  uploadedMessage = "Uploaded",
  uploadFailed = "Upload failed",
  nameLabel = "Name",
  typeLabel = "Type",
  sizeLabel = "Size",
  addedLabel = "Added",
  deleteTitle = "Delete file",
  deleteDescription = "The file is removed from the library.",
  deleteLabel = "Delete",
  viewLabel = "View",
  accept = "image/*,video/mp4,video/webm",
  typeError = "That file type is not allowed.",
}: MediaLibraryProps) {
  const [view, setView] = React.useState<"grid" | "table">("grid")
  const activeUploads = React.useRef(0)
  const [sort, setSort] = React.useState<SortKey>("createdAt")
  const [dir, setDir] = React.useState<"asc" | "desc">("desc")
  const [busy, setBusy] = React.useState(false)
  const [pendingId, setPendingId] = React.useState<string | null>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)

  const sorted = React.useMemo(() => {
    const copy = assets.slice()
    copy.sort((a, b) => {
      const factor = dir === "asc" ? 1 : -1
      if (sort === "filename") return a.filename.localeCompare(b.filename) * factor
      if (sort === "size") return (a.size - b.size) * factor
      return a.createdAt.localeCompare(b.createdAt) * factor
    })
    return copy
  }, [assets, dir, sort])

  async function take(file: File | undefined) {
    if (!file) return
    if (!matchesAccept(file, accept)) {
      toast.error(typeError)
      return
    }
    activeUploads.current += 1
    setBusy(true)
    try {
      await onUpload(file)
      toast.success(uploadedMessage)
    } catch (error) {
      toast.error(error instanceof Error ? error.message : uploadFailed)
    } finally {
      activeUploads.current = Math.max(0, activeUploads.current - 1)
      if (activeUploads.current === 0) setBusy(false)
    }
  }

  function toggleSort(key: SortKey) {
    if (sort === key) setDir((current) => (current === "asc" ? "desc" : "asc"))
    else {
      setSort(key)
      setDir(key === "filename" ? "asc" : "desc")
    }
  }

  return (
    <div className={cn("flex flex-col gap-3", className)}>
      <div className="flex flex-wrap items-center gap-2">
        <Button type="button" disabled={busy} onClick={() => inputRef.current?.click()}>
          <Upload />
          {busy ? uploadingLabel : uploadLabel}
        </Button>
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          className="sr-only"
          onChange={(event) => {
            void take(event.target.files?.[0])
            event.target.value = ""
          }}
        />
        <div
          className="flex min-h-9 flex-1 items-center justify-center rounded-lg border border-dashed border-border px-3 text-xs text-muted-foreground"
          onDragOver={(event) => event.preventDefault()}
          onDrop={(event) => {
            event.preventDefault()
            void take(event.dataTransfer.files[0])
          }}
        >
          {dropLabel}
        </div>
        <div className="flex rounded-lg bg-muted p-0.5" role="group" aria-label={viewLabel}>
          <Button type="button" size="icon-sm" variant={view === "grid" ? "secondary" : "ghost"} aria-pressed={view === "grid"} onClick={() => setView("grid")}>
            <LayoutGrid />
          </Button>
          <Button type="button" size="icon-sm" variant={view === "table" ? "secondary" : "ghost"} aria-pressed={view === "table"} onClick={() => setView("table")}>
            <List />
          </Button>
        </div>
      </div>
      {sorted.length === 0 ? (
        <EmptyState title={emptyTitle} description={emptyDescription} />
      ) : view === "grid" ? (
        <ul className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
          {sorted.map((asset) => (
            <li key={asset.id} className="overflow-hidden rounded-xl bg-card ring-1 ring-foreground/10">
              <MediaPreview asset={asset} />
              <div className="flex items-center gap-2 px-2 py-2">
                <div className="min-w-0 flex-1">
                  <p className="truncate text-xs font-medium">{asset.filename}</p>
                  <p className="text-xs text-muted-foreground">{formatBytes(asset.size)}</p>
                </div>
                <Button type="button" variant="ghost" size="icon-sm" aria-label={`${deleteLabel} ${asset.filename}`} onClick={() => setPendingId(asset.id)}>
                  <Trash2 />
                </Button>
              </div>
            </li>
          ))}
        </ul>
      ) : (
        <div className="overflow-x-auto rounded-xl ring-1 ring-foreground/10">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>
                  <button type="button" onClick={() => toggleSort("filename")}>{nameLabel}</button>
                </TableHead>
                <TableHead>{typeLabel}</TableHead>
                <TableHead>
                  <button type="button" onClick={() => toggleSort("size")}>{sizeLabel}</button>
                </TableHead>
                <TableHead>
                  <button type="button" onClick={() => toggleSort("createdAt")}>{addedLabel}</button>
                </TableHead>
                <TableHead />
              </TableRow>
            </TableHeader>
            <TableBody>
              {sorted.map((asset) => (
                <TableRow key={asset.id}>
                  <TableCell className="max-w-48 truncate">{asset.filename}</TableCell>
                  <TableCell>{asset.mime}</TableCell>
                  <TableCell>{formatBytes(asset.size)}</TableCell>
                  <TableCell>{formatWhen(Date.parse(asset.createdAt))}</TableCell>
                  <TableCell>
                    <Button type="button" variant="ghost" size="icon-sm" aria-label={`${deleteLabel} ${asset.filename}`} onClick={() => setPendingId(asset.id)}>
                      <Trash2 />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      )}
      <ConfirmDelete
        open={pendingId != null}
        onOpenChange={(open) => {
          if (!open) setPendingId(null)
        }}
        title={deleteTitle}
        description={deleteDescription}
        onConfirm={async () => {
          if (pendingId) await onDelete(pendingId)
          setPendingId(null)
        }}
      />
    </div>
  )
}

function MediaPreview({ asset }: { asset: MediaAsset }) {
  if (isVideo(asset.mime, asset.url)) {
    return <video src={asset.url} className="aspect-video w-full bg-muted object-cover" muted playsInline />
  }
  if (!asset.url) {
    return <div className="grid aspect-video place-items-center bg-muted text-xs text-muted-foreground">File</div>
  }
  // eslint-disable-next-line @next/next/no-img-element
  return <img src={asset.url} alt="" className="aspect-video w-full bg-muted object-cover" />
}

"use client"

import * as React from "react"
import { flexRender } from "@tanstack/react-table"
import {
  getCoreRowModel,
  getSortedRowModel,
  useLegacyTable,
  type LegacyColumnDef,
} from "@tanstack/react-table/legacy"
import type { RowSelectionState, SortingState } from "@tanstack/react-table"
import {
  ArrowDown,
  ArrowUp,
  ArrowUpDown,
  Columns3,
  Download,
  Search,
} from "lucide-react"
import { toast } from "sonner"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { downloadCsv, toCsv, type CsvColumn } from "@/lib/csv"
import { EmptyState } from "@/components/ui/entity-form"

export type DataTableTab<T> = {
  id: string
  label: string
  predicate?: (row: T) => boolean
}

export type DataTableFilter<T> = {
  id: string
  label: string
  options: { value: string; label: string }[]
  predicate: (row: T, value: string) => boolean
}

export type DataTableBulkAction<T> = {
  id: string
  label: string
  destructive?: boolean
  onAction: (rows: T[]) => Promise<void> | void
}

export type AdminDataTableProps<T extends { id: string }> = {
  data: readonly T[]
  columns: LegacyColumnDef<T>[]
  tabs?: readonly DataTableTab<T>[]
  filters?: readonly DataTableFilter<T>[]
  searchText?: (row: T) => string
  searchPlaceholder?: string
  bulkActions?: readonly DataTableBulkAction<T>[]
  csvColumns?: readonly CsvColumn[]
  csvFilename?: string
  toCsvRow?: (row: T) => Record<string, unknown>
  renderDetail?: (row: T) => React.ReactNode
  detailTitle?: (row: T) => string
  className?: string
  emptyTitle?: string
  columnsLabel?: string
  csvLabel?: string
  selectedLabel?: string
  previousLabel?: string
  nextLabel?: string
  detailFallback?: string
  detailDescription?: string
  viewsLabel?: string
  selectAllLabel?: string
  selectRowLabel?: string
  actionErrorLabel?: string
}

export function AdminDataTable<T extends { id: string }>({
  data,
  columns,
  tabs,
  filters,
  searchText,
  searchPlaceholder = "Search",
  bulkActions,
  csvColumns,
  csvFilename = "export.csv",
  toCsvRow,
  renderDetail,
  detailTitle,
  className,
  emptyTitle = "No rows",
  columnsLabel = "Columns",
  csvLabel = "CSV",
  selectedLabel = "selected",
  previousLabel = "Previous",
  nextLabel = "Next",
  detailFallback = "Details",
  detailDescription = "Row details",
  viewsLabel = "Views",
  selectAllLabel = "Select all",
  selectRowLabel = "Select row",
  actionErrorLabel = "That action failed",
}: AdminDataTableProps<T>) {
  const [tab, setTab] = React.useState(tabs?.[0]?.id ?? "all")
  const [query, setQuery] = React.useState("")
  const [filterValues, setFilterValues] = React.useState<Record<string, string>>({})
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [columnVisibility, setColumnVisibility] = React.useState<Record<string, boolean>>({})
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({})
  const [openId, setOpenId] = React.useState<string | null>(null)
  const [acting, setActing] = React.useState<string | null>(null)

  const searched = React.useMemo(() => {
    const q = query.trim().toLowerCase()
    return data.filter((row) => {
      if (q && searchText && !searchText(row).toLowerCase().includes(q)) return false
      for (const filter of filters ?? []) {
        const value = filterValues[filter.id]
        if (value && value !== "any" && !filter.predicate(row, value)) return false
      }
      return true
    })
  }, [data, filterValues, filters, query, searchText])

  const counts = React.useMemo(() => {
    const map = new Map<string, number>()
    for (const item of tabs ?? []) {
      map.set(
        item.id,
        item.predicate ? searched.filter(item.predicate).length : searched.length,
      )
    }
    return map
  }, [searched, tabs])

  const rows = React.useMemo(() => {
    const current = tabs?.find((item) => item.id === tab)
    if (!current?.predicate) return searched
    return searched.filter(current.predicate)
  }, [searched, tab, tabs])

  const selectionColumn: LegacyColumnDef<T> = {
    id: "select",
    enableSorting: false,
    enableHiding: false,
    header: ({ table }) => (
      <Checkbox
        checked={
          table.getIsAllRowsSelected()
            ? true
            : table.getIsSomeRowsSelected()
              ? "indeterminate"
              : false
        }
        onCheckedChange={(value) => table.toggleAllRowsSelected(value === true)}
        aria-label={selectAllLabel}
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        checked={row.getIsSelected()}
        onCheckedChange={(value) => row.toggleSelected(value === true)}
        aria-label={selectRowLabel}
        onClick={(event) => event.stopPropagation()}
      />
    ),
  }

  const table = useLegacyTable({
    data: rows,
    columns: [selectionColumn, ...columns],
    state: { sorting, columnVisibility, rowSelection },
    onSortingChange: setSorting,
    onColumnVisibilityChange: setColumnVisibility,
    onRowSelectionChange: setRowSelection,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getRowId: (row) => row.id,
    enableRowSelection: true,
  })

  const selected = table.getSelectedRowModel().rows.map((row) => row.original)
  const visibleRows = table.getRowModel().rows.map((row) => row.original)
  const openIndex = visibleRows.findIndex((row) => row.id === openId)
  const openRow = openIndex >= 0 ? visibleRows[openIndex] : undefined

  function exportCsv(source: readonly T[]) {
    if (!csvColumns || !toCsvRow) return
    downloadCsv(csvFilename, toCsv(source.map(toCsvRow), csvColumns))
  }

  return (
    <div className={cn("flex flex-col gap-3", className)}>
      <div className="flex flex-col gap-3">
        {tabs && tabs.length > 0 ? (
          <div className="flex flex-wrap gap-1" role="tablist" aria-label={viewsLabel}>
            {tabs.map((item) => (
              <Button
                key={item.id}
                type="button"
                size="sm"
                role="tab"
                variant={tab === item.id ? "secondary" : "ghost"}
                aria-selected={tab === item.id}
                onClick={() => {
                  setTab(item.id)
                  setRowSelection({})
                }}
              >
                {item.label}
                <Badge variant="outline" className="tabular-nums">
                  {counts.get(item.id) ?? 0}
                </Badge>
              </Button>
            ))}
          </div>
        ) : null}
        <div className="flex flex-wrap items-center gap-2">
          <div className="relative min-w-40 flex-1 sm:max-w-xs">
            <Search className="pointer-events-none absolute top-1/2 left-2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              placeholder={searchPlaceholder}
              aria-label={searchPlaceholder}
              className="pl-8"
            />
          </div>
          {(filters ?? []).map((filter) => (
            <Select
              key={filter.id}
              value={filterValues[filter.id] ?? "any"}
              onValueChange={(value) =>
                setFilterValues((current) => ({ ...current, [filter.id]: value }))
              }
            >
              <SelectTrigger className="w-40" aria-label={filter.label}>
                <SelectValue placeholder={filter.label} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="any">{filter.label}</SelectItem>
                {filter.options.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          ))}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button type="button" variant="outline" size="sm">
                <Columns3 />
                {columnsLabel}
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end">
              <DropdownMenuLabel>{columnsLabel}</DropdownMenuLabel>
              {table
                .getAllLeafColumns()
                .filter((column) => column.getCanHide())
                .map((column) => (
                  <DropdownMenuCheckboxItem
                    key={column.id}
                    checked={column.getIsVisible()}
                    onCheckedChange={(value) => column.toggleVisibility(value === true)}
                  >
                    {typeof column.columnDef.header === "string" ? column.columnDef.header : column.id}
                  </DropdownMenuCheckboxItem>
                ))}
            </DropdownMenuContent>
          </DropdownMenu>
          {csvColumns ? (
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={() => exportCsv(selected.length ? selected : visibleRows)}
            >
              <Download />
              {csvLabel}
            </Button>
          ) : null}
        </div>
        {selected.length > 0 && bulkActions && bulkActions.length > 0 ? (
          <div className="flex flex-wrap items-center gap-2 rounded-lg bg-muted px-3 py-2 text-sm">
            <span className="tabular-nums">
              {selected.length} {selectedLabel}
            </span>
            {bulkActions.map((action) => (
              <Button
                key={action.id}
                type="button"
                size="sm"
                variant={action.destructive ? "destructive" : "secondary"}
                disabled={acting != null}
                onClick={() => {
                  setActing(action.id)
                  void (async () => {
                    try {
                      await action.onAction(selected)
                      setRowSelection({})
                    } catch (error) {
                      toast.error(error instanceof Error && error.message ? error.message : actionErrorLabel)
                    } finally {
                      setActing(null)
                    }
                  })()
                }}
              >
                {action.label}
              </Button>
            ))}
          </div>
        ) : null}
      </div>

      <div className="overflow-x-auto rounded-xl ring-1 ring-foreground/10">
        <Table>
          <TableHeader>
            {table.getHeaderGroups().map((group) => (
              <TableRow key={group.id}>
                {group.headers.map((header) => {
                  const sorted = header.column.getIsSorted()
                  return (
                    <TableHead key={header.id}>
                      {header.isPlaceholder ? null : header.column.getCanSort() ? (
                        <button
                          type="button"
                          className="inline-flex items-center gap-1"
                          onClick={header.column.getToggleSortingHandler()}
                        >
                          {flexRender(header.column.columnDef.header, header.getContext())}
                          {sorted === "asc" ? (
                            <ArrowUp className="size-3" />
                          ) : sorted === "desc" ? (
                            <ArrowDown className="size-3" />
                          ) : (
                            <ArrowUpDown className="size-3 opacity-40" />
                          )}
                        </button>
                      ) : (
                        flexRender(header.column.columnDef.header, header.getContext())
                      )}
                    </TableHead>
                  )
                })}
              </TableRow>
            ))}
          </TableHeader>
          <TableBody>
            {table.getRowModel().rows.length === 0 ? (
              <TableRow>
                <TableCell colSpan={table.getVisibleLeafColumns().length}>
                  <EmptyState title={emptyTitle} />
                </TableCell>
              </TableRow>
            ) : (
              table.getRowModel().rows.map((row) => (
                <TableRow
                  key={row.id}
                  data-state={row.getIsSelected() ? "selected" : undefined}
                  className={renderDetail ? "cursor-pointer" : undefined}
                  tabIndex={renderDetail ? 0 : undefined}
                  onClick={() => {
                    if (renderDetail) setOpenId(row.original.id)
                  }}
                  onKeyDown={(event) => {
                    if (!renderDetail) return
                    if (event.target !== event.currentTarget) return
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault()
                      setOpenId(row.original.id)
                    }
                  }}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id}>
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </TableCell>
                  ))}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {renderDetail ? (
        <Sheet open={openRow != null} onOpenChange={(open) => !open && setOpenId(null)}>
          <SheetContent className="w-full overflow-y-auto sm:max-w-md">
            <SheetHeader>
              <SheetTitle>{openRow ? (detailTitle?.(openRow) ?? detailFallback) : detailFallback}</SheetTitle>
              <SheetDescription className="sr-only">{detailDescription}</SheetDescription>
            </SheetHeader>
            <div className="flex items-center gap-2 px-4">
              <Button
                type="button"
                size="sm"
                variant="outline"
                disabled={openIndex <= 0}
                onClick={() => {
                  const prev = visibleRows[openIndex - 1]
                  if (prev) setOpenId(prev.id)
                }}
              >
                {previousLabel}
              </Button>
              <Button
                type="button"
                size="sm"
                variant="outline"
                disabled={openIndex < 0 || openIndex >= visibleRows.length - 1}
                onClick={() => {
                  const next = visibleRows[openIndex + 1]
                  if (next) setOpenId(next.id)
                }}
              >
                {nextLabel}
              </Button>
            </div>
            <div className="px-4 pb-6">{openRow ? renderDetail(openRow) : null}</div>
          </SheetContent>
        </Sheet>
      ) : null}
    </div>
  )
}

