export const RANGE_OPTIONS = [
  { key: "today", label: "Today" },
  { key: "7d", label: "Last 7 days" },
  { key: "30d", label: "Last 30 days" },
  { key: "90d", label: "Last 90 days" },
  { key: "12m", label: "Last 12 months" },
] as const

export type RangeKey = (typeof RANGE_OPTIONS)[number]["key"]

export type ResolvedRange = {
  key: RangeKey
  label: string
  from: number
  to: number
  prevFrom: number
  prevTo: number
  bucket: "hour" | "day" | "month"
}

const DAY = 86_400_000

export function isRangeKey(value: string): value is RangeKey {
  return RANGE_OPTIONS.some((option) => option.key === value)
}

/** Offset of `timeZone` at `ts`, in ms. UTC is 0. */
export function timeZoneOffsetMs(timeZone: string, ts: number): number {
  const formatted = new Intl.DateTimeFormat("en-US", {
    timeZone,
    hourCycle: "h23",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }).formatToParts(new Date(ts))
  const parts = Object.fromEntries(formatted.map((part) => [part.type, part.value]))
  const asUtc = Date.UTC(
    Number(parts.year),
    Number(parts.month) - 1,
    Number(parts.day),
    Number(parts.hour) % 24,
    Number(parts.minute),
    Number(parts.second),
  )
  return asUtc - ts
}

/** Move a zoned midnight by whole calendar days, including 23h and 25h DST days. */
export function addZonedDays(dayStart: number, days: number, timeZone = "UTC"): number {
  return startOfZonedDay(dayStart + days * DAY + 12 * 3_600_000, timeZone)
}

export function startOfZonedDay(ts: number, timeZone = "UTC"): number {
  const offset = timeZoneOffsetMs(timeZone, ts)
  const local = ts + offset
  const midnightLocal = Math.floor(local / DAY) * DAY
  const guess = midnightLocal - timeZoneOffsetMs(timeZone, midnightLocal - offset)
  const check = timeZoneOffsetMs(timeZone, guess)
  return midnightLocal - check
}

export function resolveRange(
  key: RangeKey,
  now = Date.now(),
  timeZone = "UTC",
): ResolvedRange {
  const option = RANGE_OPTIONS.find((item) => item.key === key) ?? RANGE_OPTIONS[1]
  const today = startOfZonedDay(now, timeZone)
  let from = today
  let bucket: ResolvedRange["bucket"] = "day"
  let span = DAY

  if (key === "today") {
    from = today
    bucket = "hour"
    span = addZonedDays(today, 1, timeZone) - today
  } else if (key === "12m") {
    const offset = timeZoneOffsetMs(timeZone, today)
    const local = new Date(today + offset)
    const start = Date.UTC(local.getUTCFullYear(), local.getUTCMonth() - 11, 1)
    from = start - timeZoneOffsetMs(timeZone, start - offset)
    bucket = "month"
    span = now - from
  } else {
    const days = key === "7d" ? 7 : key === "30d" ? 30 : 90
    from = addZonedDays(today, -(days - 1), timeZone)
    span = addZonedDays(today, 1, timeZone) - from
    bucket = "day"
  }

  return {
    key: option.key,
    label: option.label,
    from,
    to: now,
    prevFrom: from - span,
    prevTo: now - span,
    bucket,
  }
}

/** Inclusive window. */
export function inRange(ts: number, from: number, to: number): boolean {
  return ts >= from && ts <= to
}

export function filterByRange<T>(
  rows: readonly T[],
  getTime: (row: T) => number | null,
  from: number,
  to: number,
): T[] {
  return rows.filter((row) => {
    const ts = getTime(row)
    return ts != null && inRange(ts, from, to)
  })
}

export type DatePreset = {
  key: string
  label: string
}

export const CALL_PRESETS: DatePreset[] = [
  { key: "any", label: "Any time" },
  { key: "today", label: "Today" },
  { key: "tomorrow", label: "Tomorrow" },
  { key: "next7", label: "Next 7 days" },
  { key: "next30", label: "Next 30 days" },
  { key: "last7", label: "Last 7 days" },
  { key: "last30", label: "Last 30 days" },
]

/** `[from, to)` for a named preset, or null when the preset does not filter. */
export function presetBounds(
  preset: string,
  now = Date.now(),
  timeZone = "UTC",
): [number, number] | null {
  const today = startOfZonedDay(now, timeZone)
  switch (preset) {
    case "today":
      return [today, addZonedDays(today, 1, timeZone)]
    case "tomorrow":
      return [addZonedDays(today, 1, timeZone), addZonedDays(today, 2, timeZone)]
    case "next7":
      return [now, now + 7 * DAY]
    case "next30":
      return [now, now + 30 * DAY]
    case "last7":
      return [now - 7 * DAY, now]
    case "last30":
      return [now - 30 * DAY, now]
    case "last90":
      return [now - 90 * DAY, now]
    default:
      return null
  }
}

import type {
  AnalyticsClick,
  AnalyticsSnapshot,
  AnalyticsView,
  DailyMetric,
  LabeledValue,
} from "@/lib/admin-types"
import { inRange } from "@/lib/date-range"

const DAY = 86_400_000

function dateKey(ts: number): string {
  return new Date(ts).toISOString().slice(0, 10)
}

function hostOf(referrer: string | null): string {
  if (!referrer) return "Directo"
  try {
    const url = referrer.includes("://") ? new URL(referrer) : new URL(`https://${referrer}`)
    return url.host.replace(/^www\./, "") || "Directo"
  } catch {
    return referrer
  }
}

function bump(map: Map<string, number>, key: string, by = 1) {
  map.set(key, (map.get(key) ?? 0) + by)
}

function top(map: Map<string, number>, limit: number): LabeledValue[] {
  return [...map.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, limit)
    .map(([label, value]) => ({ label, value }))
}

/**
 * Turn raw page views and clicks into the snapshot the chart pieces render.
 * The window is inclusive. Empty days inside the window stay in `daily`.
 */
export function summarizeAnalytics(
  views: readonly AnalyticsView[],
  clicks: readonly AnalyticsClick[],
  from: number,
  to: number,
): AnalyticsSnapshot {
  const inWindow = views.filter((view) => inRange(view.ts, from, to))
  const clicksInWindow = clicks.filter((click) => inRange(click.ts, from, to))

  const visitorsByDay = new Map<string, Set<string>>()
  const viewsByDay = new Map<string, number>()
  const clicksByDay = new Map<string, number>()
  const sources = new Map<string, number>()
  const sessions = new Set<string>()
  const pricingSessions = new Set<string>()
  const clickSessions = new Set<string>()
  const heat: number[][] = Array.from({ length: 7 }, () => Array.from({ length: 24 }, () => 0))
  const scroll = { s25: 0, s50: 0, s75: 0, s90: 0, s100: 0 }

  for (const view of inWindow) {
    const key = dateKey(view.ts)
    const set = visitorsByDay.get(key) ?? new Set<string>()
    set.add(view.visitor)
    visitorsByDay.set(key, set)
    bump(viewsByDay, key)
    bump(sources, hostOf(view.referrer))
    sessions.add(view.session)
    if (view.path.includes("precio") || view.path.includes("pricing") || view.path.includes("planes")) {
      pricingSessions.add(view.session)
    }
    const date = new Date(view.ts)
    const mondayIndex = (date.getUTCDay() + 6) % 7
    const hour = date.getUTCHours()
    const row = heat[mondayIndex]
    if (row) row[hour] = (row[hour] ?? 0) + 1
    if (view.scrollPct >= 25) scroll.s25 += 1
    if (view.scrollPct >= 50) scroll.s50 += 1
    if (view.scrollPct >= 75) scroll.s75 += 1
    if (view.scrollPct >= 90) scroll.s90 += 1
    if (view.scrollPct >= 100) scroll.s100 += 1
  }

  for (const click of clicksInWindow) {
    bump(clicksByDay, dateKey(click.ts))
    clickSessions.add(click.session)
  }

  const daily: DailyMetric[] = []
  const start = Date.parse(`${dateKey(from)}T00:00:00.000Z`)
  const end = Date.parse(`${dateKey(to)}T00:00:00.000Z`)
  for (let ts = start; ts <= end; ts += DAY) {
    const key = dateKey(ts)
    daily.push({
      date: key,
      visitors: visitorsByDay.get(key)?.size ?? 0,
      views: viewsByDay.get(key) ?? 0,
      clicks: clicksByDay.get(key) ?? 0,
    })
  }

  const total = inWindow.length || 1
  const scrollBars: LabeledValue[] = [
    { label: "25%", value: scroll.s25 / total },
    { label: "50%", value: scroll.s50 / total },
    { label: "75%", value: scroll.s75 / total },
    { label: "90%", value: scroll.s90 / total },
    { label: "100%", value: scroll.s100 / total },
  ]

  return {
    daily,
    sources: top(sources, 6),
    funnel: [
      { label: "Sesiones", value: sessions.size },
      { label: "Vieron precios", value: pricingSessions.size },
      { label: "Hicieron clic", value: clickSessions.size },
    ],
    scroll: scrollBars,
    heat,
  }
}

export function sumDaily(daily: readonly DailyMetric[]) {
  return daily.reduce(
    (acc, day) => ({
      visitors: acc.visitors + day.visitors,
      views: acc.views + day.views,
      clicks: acc.clicks + day.clicks,
    }),
    { visitors: 0, views: 0, clicks: 0 },
  )
}

"use client"

import * as React from "react"

import { reorderVisible } from "@/lib/reorder"

export type ListNotify = {
  success: (message: string) => void
  error: (message: string) => void
}

type UseOptimisticListOptions<T extends { id: string }> = {
  items: readonly T[]
  onReorder: (ids: readonly string[]) => Promise<void> | void
  notify?: ListNotify
  savedMessage?: string
  errorMessage?: string
}

/** Prior order, plus any ids that arrived while the save was in flight. */
export function restoreOrder(before: readonly string[], currentIds: readonly string[]) {
  const live = new Set(currentIds)
  const kept = before.filter((id) => live.has(id))
  const seen = new Set(kept)
  for (const id of currentIds) {
    if (!seen.has(id)) kept.push(id)
  }
  return kept
}

/**
 * Shows the next order immediately. If `onReorder` rejects, the previous
 * order is restored and `notify.error` runs.
 */
export function useOptimisticList<T extends { id: string }>({
  items,
  onReorder,
  notify,
  savedMessage = "Order saved",
  errorMessage = "Could not save the order",
}: UseOptimisticListOptions<T>) {
  const idsKey = items.map((item) => item.id).join("\0")
  const [order, setOrder] = React.useState(() => items.map((item) => item.id))
  const [seen, setSeen] = React.useState(idsKey)
  const [pending, setPending] = React.useState(false)
  const inFlight = React.useRef(false)
  const itemsRef = React.useRef(items)
  React.useEffect(() => {
    itemsRef.current = items
  }, [items])

  if (seen !== idsKey) {
    setSeen(idsKey)
    setOrder(items.map((item) => item.id))
  }

  const byId = React.useMemo(() => new Map(items.map((item) => [item.id, item])), [items])
  const ordered = order.map((id) => byId.get(id)).filter((item): item is T => item != null)

  const commit = React.useCallback(
    async (next: readonly string[]) => {
      if (inFlight.current) return
      const before = order
      if (before.join("\0") === next.join("\0")) return
      inFlight.current = true
      setOrder([...next])
      setPending(true)
      try {
        await onReorder(next)
        notify?.success(savedMessage)
      } catch (error) {
        setOrder(restoreOrder(before, itemsRef.current.map((item) => item.id)))
        const message = error instanceof Error && error.message ? error.message : errorMessage
        notify?.error(message)
      } finally {
        inFlight.current = false
        setPending(false)
      }
    },
    [errorMessage, notify, onReorder, order, savedMessage],
  )

  const moveVisible = React.useCallback(
    (visibleIds: readonly string[], activeId: string, overId: string) => {
      const next = reorderVisible(order, visibleIds, activeId, overId)
      void commit(next)
    },
    [commit, order],
  )

  return { items: ordered, order, pending, commit, moveVisible }
}

