      name: row.name,
      role: row.role,
      avatar_url: row.avatarUrl,
      position: row.position,
      published: row.published,
    })),
    faqs: contentPort<Faq>(client, "faqs", (row) => ({
      id: str(row, "id"),
      question: str(row, "question"),
      answer: str(row, "answer"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      question: row.question,
      answer: row.answer,
      position: row.position,
      published: row.published,
    })),
    plans: plansPort(client),
    experience: contentPort<Experience>(client, "experience", (row) => ({
      id: str(row, "id"),
      role: str(row, "role"),
      company: str(row, "company"),
      period: str(row, "period"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      role: row.role,
      company: row.company,
      period: row.period,
      position: row.position,
      published: row.published,
    })),
    awards: contentPort(client, "awards", (row) => ({
      id: str(row, "id"),
      name: str(row, "name"),
      count: str(row, "count"),
      href: str(row, "href"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      name: row.name,
      count: row.count,
      href: row.href,
      position: row.position,
      published: row.published,
    })),
    stats: contentPort(client, "about_stats", (row) => ({
      id: str(row, "id"),
      value: str(row, "value"),
      label: str(row, "label"),
      position: num(row, "position"),
      published: bool(row, "published"),
    }), (row) => ({
      id: row.id,
      value: row.value,
      label: row.label,
      position: row.position,
      published: row.published,
    })),
    media: createSupabaseMedia(client, bucket),
    bookings: {
      async list() {
        const rows = await selectPages((from, to) =>
          client.from("bookings").select("*").order("created_at", { ascending: false }).range(from, to),
        )
        return rows.map(bookingFrom)
      },
      async save(row: Booking) {
        const payload = {
          id: row.id,
          name: row.name,
          email: row.email,
          phone: row.phone,
          needs: row.needs,
          plan: row.plan,
          note: row.note,
          source: row.source,
          came_from: row.cameFrom,
          status: row.status,
          start_time: row.startTime,
          end_time: row.endTime,
          timezone: row.timezone,
          meet_url: row.meetUrl,
          created_at: row.createdAt,
          updated_at: Date.now(),
        }
        const { data, error } = await client.from("bookings").upsert(payload).select("*").single()
        await throwIf(error)
        return bookingFrom(asRow(data))
      },
      async remove(id: string) {
        await throwIf((await client.from("bookings").delete().eq("id", id)).error)
      },
      async removeMany(ids: readonly string[]) {
        await throwIf((await client.from("bookings").delete().in("id", [...ids])).error)
      },
    },
    /** Load feature lines and attach them to plans. `plans.list()` already does this. */
    hydratePlanFeatures(plans: Plan[]) {
      return loadPlanFeatures(client, plans)
    },
  }
}

-- Admin kit schema for Supabase (Postgres).
-- Apply in the host project. This file does not connect to a database.
--
-- Public visitors can read rows with published = true.
-- Writes require a row in public.admins for auth.uid().
-- Bookings are not public: the site inserts them with the service role.

create table if not exists public.admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.admins where user_id = auth.uid()
  );
$$;

revoke all on function public.is_admin() from public;
grant execute on function public.is_admin() to anon, authenticated;

create table if not exists public.categories (
  id text primary key,
  title text not null,
  slug text not null unique,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.projects (
  id text primary key,
  title text not null,
  slug text not null unique,
  category_id text references public.categories (id) on delete set null,
  summary text not null default '',
  client text not null default '',
  year text not null default '',
  live_url text not null default '',
  cover_url text,
  show_on_homepage boolean not null default false,
  published boolean not null default false,
  position integer not null default 0
);

create table if not exists public.settings (
  key text primary key,
  value text not null,
  updated_at timestamptz not null default now()
);

create table if not exists public.clients (
  id text primary key,
  name text not null,
  logo_url text,
  row_index integer not null default 0,
  position integer not null default 0,
  published boolean not null default false
);

create table if not exists public.photos (
  id text primary key,
  src text not null default '',
  alt text not null default '',
  show_on_homepage boolean not null default false,
  position integer not null default 0,
  published boolean not null default false
